-- Hotspot'lar: alt yapılar için içerik hotspot'ları + külliyelerde alt yapılara yönlendiren hotspot'lar.
-- Tüm açıklamalar Vakıf Katılım Bursa envanter kitaplarından (Cilt 1 ve 2) derlenmiştir.
-- Konumlar fotoğrafa göre (0-1, sol üstten) verilmiştir; 'after' = sol (tarihî) fotoğraf, 'before' = sağ (güncel).
-- Yeşil İmareti'nin tarihî görseli olmadığı için hotspot'ları güncel fotoğrafa ('before') konuldu.
-- Yönlendirme hotspot'larındaki konumlar hava fotoğrafında yaklaşık belirlendi; kaymışsa x/y güncellenebilir.

-- 1) Yönlendirme için kolon: hotspot'un gideceği alt eserin id'si
alter table public."Hotspots"
  add column if not exists target_place_id bigint references public.heritage_places(id) on delete set null;

-- 2) Muradiye'de var olan iki hotspot da ilgili yapıya yönlendirsin
update public."Hotspots" set target_place_id = 17 where id = 16; -- Muradiye Camii
update public."Hotspots" set target_place_id = 18 where id = 18; -- Muradiye Medresesi

-- 3) Yeni hotspot'lar

-- 4) Kimlik sayacını son id'ye getir (sonradan panelden eklenen satırlar çakışmasın)
select setval(pg_get_serial_sequence('"Hotspots"', 'id'), (select max(id) from public."Hotspots"));
