insert into public."Hotspots"
  (id, place_id, title, description, target_side, x_percent, y_percent, title_en, description_en, target_place_id)
values
  (51, 17, 'İnşa Kitabesi', 'Ana giriş kapısının üzerindeki kitabe, camiye Receb 828 (1425) tarihinde başlandığını ve Muharrem 830 (1426) ayında tamamlandığını belgeler.', 'after', 0.45, 0.72, 'Foundation Inscription', 'The inscription above the main door records that building began in 1425 and was completed in 1426.', null),
  (52, 17, 'Beş Bölümlü Son Cemaat Yeri', 'Dört mermer paye üzerine oturan revakların arasında iki granit sütun vardır. Orta giriş bölümü mukarnaslı bir kubbeyle örtülüdür.', 'after', 0.6, 0.68, 'Five-Bay Portico', 'Between the arcades on four marble piers stand two granite columns. The central entrance bay is covered by a muqarnas dome.', null),
  (53, 17, 'Kubbeler ve Tabhaneler', 'Giriş sofasının iki yanında art arda yükselen kubbeler, Bursa''daki sultan camilerinin sonuncusunda uygulanan tabhaneli plan şemasını gösterir.', 'after', 0.44, 0.5, 'Domes and Lodge Rooms', 'The domes rising one after another on either side of the entrance hall show the lodge (tabhane) plan of Bursa''s last sultanic mosque.', null),
  (54, 17, 'Tuğla Minareler', 'Caminin iki tuğla minaresinden doğudaki daha eskidir. Ona hem camiden hem asma kattan girilebilir.', 'after', 0.37, 0.48, 'Brick Minarets', 'Of the mosque''s two brick minarets, the eastern one is older. It can be entered from both the mosque and the mezzanine.', null),
  (55, 18, 'Taç Kapı', 'Kuzey cephedeki taç kapı, sivri kemerli bir eyvan biçiminde tasarlanmış; mukarnaslı tromplu kubbeyle örtülüdür.', 'after', 0.4, 0.68, 'Crown Portal', 'The north portal is designed as a pointed-arch iwan covered by a dome on muqarnas squinches.', null),
  (56, 18, 'Dershane Kubbesi', 'Dershane kubbeli ve tromplu yapıdadır. Duvarlar çini panolarla, diğer yüzeyler geometrik tuğla işçiliğiyle süslüdür.', 'after', 0.56, 0.22, 'Lecture Hall Dome', 'The lecture hall is domed and set on squinches. Its walls are decorated with tile panels and its other surfaces with geometric brickwork.', null),
  (57, 18, 'Hücre Revakları', 'On altı öğrenci hücresinin önünde revak sırası uzanır; doğu ve batı yönünde kubbeli, kuzeyde tonoz örtülüdür.', 'after', 0.68, 0.43, 'Cell Arcades', 'An arcade runs in front of the sixteen student cells, domed on the east and west sides and vaulted on the north.', null),
  (58, 18, 'Avlunun Cam Örtüsü', 'Açık avlulu medresenin üstü, son restorasyonda çelik konstrüksiyonlu bir cam örtüyle kapatılmıştır.', 'after', 0.72, 0.52, 'Glass Cover of the Courtyard', 'The open courtyard of the madrasa was covered with a steel-framed glass roof in the latest restoration.', null),
  (59, 19, 'Kapı Üstündeki Kitabe', 'Kapının üzerinde mermer zemine celi sülüs hatla yazılmış üç satırlık kitabe vardır. Kitabe 1 Muharrem 855 (1451) tarihlidir.', 'after', 0.62, 0.38, 'Inscription Above the Door', 'Above the door, a three-line inscription in thuluth script is set on marble. It is dated 1 Muharram 855 (1451).', null),
  (60, 19, 'Sofalı Giriş', 'Oğlu II. Mehmed''in yaptırdığı türbe kare planlıdır ve dört yönden sofalıdır.', 'after', 0.66, 0.52, 'Porch Entrance', 'Built by his son Mehmed II, the tomb is square in plan and has porches on four sides.', null),
  (61, 19, 'Sandukasız Mezar', 'II. Murad''ın vasiyeti gereği türbede sanduka ve kripta yoktur. Naaşı doğrudan toprağa defnedilmiştir.', 'after', 0.4, 0.38, 'A Grave Without a Sarcophagus', 'In line with Murad II''s will, the tomb has no sarcophagus or crypt. He was buried directly in the earth.', null),
  (62, 20, 'Mermer Revak', 'Kesme taş ve tuğladan temiz bir işçilikle yapılan türbeye mermer bir revaktan girilir.', 'after', 0.45, 0.42, 'Marble Portico', 'The tomb, finely built of cut stone and brick, is entered through a marble portico.', null),
  (63, 20, 'Çinili İç Mekân', 'İç duvarlar 2,35 m yüksekliğe kadar firuze ve lacivert altıgen çinilerle kaplıdır. Muradiye türbeleri arasında en zengin süslemeye sahiptir.', 'after', 0.46, 0.58, 'Tiled Interior', 'The interior walls are covered up to 2.35 m in turquoise and dark blue hexagonal tiles. It has the richest decoration of the Muradiye tombs.', null),
  (64, 20, 'Altıgen Gövde ve Kubbe', 'Altıgen planlı türbe, altıgen kasnağa oturan kurşun kaplı bir kubbeyle örtülüdür ve on altı pencereyle aydınlanır.', 'after', 0.27, 0.3, 'Hexagonal Body and Dome', 'The hexagonal tomb is covered by a lead-clad dome on a hexagonal drum and lit by sixteen windows.', null),
  (65, 21, 'Taç Kapı', 'Taç kapı eyvanının iki yanında mihrap nişleri vardır. Giriş, basık kemerli, çift kanatlı sade bir ahşap kapıdan yapılır.', 'after', 0.62, 0.68, 'Crown Portal', 'Mihrab niches flank the portal iwan. The entrance is a plain double-leaf wooden door under a flattened arch.', null),
  (66, 21, 'Sekizgen Kasnak', 'Kare planlı türbe, yüksek sekizgen kasnağa oturan tromplu bir kubbeyle örtülüdür. Kasnakta sivri kemerli sağır pencereler sıralanır.', 'after', 0.58, 0.43, 'Octagonal Drum', 'The square tomb is covered by a dome on squinches rising from a tall octagonal drum lined with blind pointed-arch windows.', null),
  (67, 21, 'Kesme Taş ve Tuğla Duvar', 'Duvarlar bir sıra kesme küfeki taşı ve iki sıra tuğlayla örülmüş; taşların arasına dikey tuğlalar konarak düzgün bir görünüm sağlanmıştır.', 'after', 0.3, 0.52, 'Cut-Stone and Brick Walls', 'The walls alternate a course of cut limestone with two of brick, with vertical bricks set between the stones for a tidy look.', null),
  (68, 22, 'Mutfak ve Yemek Salonu', 'Yapı art arda iki bölümden oluşur: 26 × 10 m ölçüsünde mutfak ve 16,30 × 10 m ölçüsünde yemek salonu. İkisinin de üstü kiremit kaplı kırma çatıdır.', 'before', 0.58, 0.34, 'Kitchen and Dining Hall', 'The building has two sections in a row: a 26 × 10 m kitchen and a 16.30 × 10 m dining hall, both under tiled hipped roofs.', null),
  (69, 22, 'Moloz Taş ve Tuğla Duvar', 'Beden duvarları moloz taş ve tuğladan almaşık sistemle örülmüştür.', 'before', 0.68, 0.6, 'Rubble-Stone and Brick Walls', 'The walls are built in alternating courses of rubble stone and brick.', null),
  (70, 22, 'Giriş', 'Yapı geniş ve anıtsal bir giriş kapısına sahiptir. İmarethanede toplam yedi fırın bulunur.', 'before', 0.42, 0.72, 'Entrance', 'The building has a wide, monumental entrance. The soup kitchen has seven ovens in total.', null),
  (71, 16, 'Yeşil Camii', 'Külliyenin ana yapısı. Taç kapısı, iç mekânı ve çinileriyle çok renkli sır altı tekniğinin Osmanlı mimarisinde ilk kez uygulandığı yapıdır.', 'after', 0.67, 0.55, 'Green Mosque', 'The main building of the complex, and the first Ottoman building to use multicolour underglaze tilework.', 10),
  (72, 16, 'Yeşil Türbe', 'Çelebi Mehmed''in anıt mezarı. Firuze çinili cepheleri ve 25,5 m yüksekliğiyle Osmanlı türbeleri arasında en yüksek örnektir.', 'after', 0.3, 0.57, 'Green Tomb', 'The monumental tomb of Çelebi Mehmed. With turquoise-tiled facades and a height of 25.5 m, it is the tallest of all Ottoman tombs.', 11),
  (73, 16, 'Yeşil (Sultaniye) Medresesi', 'Osmanlı eğitim kurumlarının ilk örneklerinden biri. 36 × 38,5 m ölçüsünde, üç eyvanlı bir plana sahiptir.', 'after', 0.63, 0.38, 'Green (Sultaniye) Madrasa', 'One of the earliest Ottoman educational institutions, a 36 × 38.5 m madrasa on a three-iwan plan.', 23),
  (74, 16, 'Yeşil İmareti', 'Külliyenin yemekhanesi. Vakfiyeye göre günde iki öğün yemek, zengin fakir ayrımı yapılmadan halka sunulurdu.', 'after', 0.47, 0.63, 'Green Soup Kitchen', 'The complex''s soup kitchen. According to its endowment deed, two meals a day were served to all, rich or poor alike.', 22),
  (75, 14, 'Sultan II. Murad Türbesi', 'Muradiye türbeleri içindeki en görkemli yapı. Bursa''da sanduka ya da lahit kullanılmayan tek padişah mezarıdır.', 'after', 0.55, 0.5, 'Tomb of Sultan Murad II', 'The grandest of the Muradiye tombs, and the only sultan''s tomb in Bursa without a sarcophagus.', 19),
  (76, 14, 'Cem Sultan Türbesi', 'Altıgen planlı türbe, Muradiye türbeleri arasında en zengin süslemeye sahip olanıdır. Cem Sultan''ın cenazesi 1499''da buraya defnedildi.', 'after', 0.5, 0.57, 'Tomb of Cem Sultan', 'The hexagonal tomb has the richest decoration of the Muradiye tombs. Cem Sultan was buried here in 1499.', 20),
  (77, 14, 'Şirin Hatun Türbesi', 'II. Bayezid''in eşi Şirin Hatun''un, kendi hayattayken yaptırdığı türbe. İçinde üç sanduka bulunur.', 'after', 0.47, 0.54, 'Tomb of Şirin Hatun', 'The tomb of Şirin Hatun, wife of Bayezid II, built during her lifetime. It holds three sarcophagi.', 21);
